current_qty.first:
=ARRAYFORMULA(
  IF(A2:A = "", "",
    (
      IFERROR(VLOOKUP(A2:A, QUERY({top_light_product_purchasing!G2:G, top_light_product_purchasing!J2:J}, "SELECT Col1, SUM(Col2) WHERE Col1 IS NOT NULL GROUP BY Col1 LABEL SUM(Col2) ''"), 2, FALSE), 0) +
      IFERROR(VLOOKUP(A2:A, QUERY({top_light_sales_returns!F2:F, top_light_sales_returns!G2:G}, "SELECT Col1, SUM(Col2) WHERE Col1 IS NOT NULL GROUP BY Col1 LABEL SUM(Col2) ''"), 2, FALSE), 0)
    )
    -
    (
      IFERROR(VLOOKUP(A2:A, QUERY({top_light_sales_products!E2:E, top_light_sales_products!G2:G}, "SELECT Col1, SUM(Col2) WHERE Col1 IS NOT NULL GROUP BY Col1 LABEL SUM(Col2) ''"), 2, FALSE), 0)
    )
  )
)

unique_id.first:
=SORT(UNIQUE(TOCOL({
  FILTER(top_light_sales_returns!E2:E, top_light_sales_returns!D2:D = 3);
  FILTER(top_light_sales_products!E2:E, top_light_sales_products!D2:D = 3);
  top_light_islamic_sales_products!E2:E;
  top_light_islamic_sales_products!F2:F;
  top_light_islamic_sales_returns!E2:E;
  top_light_islamic_sales_returns!F2:F
}, 1)))
